    "supporting_evidence_ids": [
      "ev_alert_001",
      "ev_log_template_003",
      "ev_metric_006",
      "ev_metric_002",
      "ev_metric_003",
      "ev_log_template_002"
    ],
    "domain_reasoning": {
      "fault_events": "The single alert (ev_alert_001) defines the incident trigger and explicitly states a synthetic payment dependency failure caused HTTP 503 responses, providing the core narrative.",
